-- RLS policies (if not already exist)
DO $$
BEGIN
  -- Read policy
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'daep_behavior_notes' AND policyname = 'behavior_notes_tenant_read'
  ) THEN
    CREATE POLICY behavior_notes_tenant_read ON daep_behavior_notes
      FOR SELECT USING (tenant_id = get_my_tenant_id());
  END IF;

  -- Insert policy
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'daep_behavior_notes' AND policyname = 'behavior_notes_tenant_insert'
  ) THEN
    CREATE POLICY behavior_notes_tenant_insert ON daep_behavior_notes
      FOR INSERT WITH CHECK (tenant_id = get_my_tenant_id());
  END IF;

  -- Update policy (original staff or admin)
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'daep_behavior_notes' AND policyname = 'behavior_notes_update'
  ) THEN
    CREATE POLICY behavior_notes_update ON daep_behavior_notes
      FOR UPDATE USING (
        tenant_id = get_my_tenant_id()
        AND (
          staff_member = auth.uid()::text
          OR get_my_role() IN ('super_admin', 'district_admin', 'daep_admin_l1')
        )
      );
  END IF;
END $$;

