// From bulkAddPoints() in points.ts
export async function bulkAddPoints(input: BulkAddPointsInput): Promise<...> {
  const { userId, tenantId, displayName, isApprovedTeacher } = await checkDAEPStaffRole();
  const supabase = await createServerClient();

  const { placementIds, date, period, adjustment, notes } = input;

  // Verify placements exist
  const { data: validPlacements } = await supabase
    .from('daep_placements')
    .select('id')
    .eq('tenant_id', tenantId)
    .in('id', placementIds);

  // Determine approval status
  const approvalStatus = isApprovedTeacher ? 'approved' : 'pending';
  const isPublic = isApprovedTeacher;

  // Build insert records
  const entries = validPlacementIds.map((placementId) => ({
    tenant_id: tenantId,
    placement_id: placementId,
    date,
    period,
    points_earned: adjustment,
    is_base_points: false,
    notes: notes || `Bulk: ${adjustment > 0 ? '+' : ''}${adjustment} points`,
    entered_by: userId,
    approval_status: approvalStatus,
    public: isPublic,
  }));

  const { error } = await supabase.from('daep_daily_points').insert(entries);
  // ...
}
